import{_ as o,o as t,c as n,aa as a}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/news/4.5-prehledy2.png",s="/buildary-help-preview/media/cs/news/4.5-vyzkouset_ai.png",l="/buildary-help-preview/media/cs/news/4.5-zadani_pro_ai.png",r="/buildary-help-preview/media/cs/news/4.5-generovani_ai.png",y=JSON.parse('{"title":"Novinky verze 4.5","description":"","frontmatter":{"title":"Novinky verze 4.5","wiki":"cs:news:vrsion_4.5"},"headers":[],"relativePath":"news/version_4-5.md","filePath":"news/version_4-5.md","lastUpdated":1793708206000}'),p={name:"news/version_4-5.md"};function v(d,e,u,c,m,k){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="novinky-verze-4-5" tabindex="-1">Novinky verze 4.5 <a class="header-anchor" href="#novinky-verze-4-5" aria-label="Permalink to &quot;Novinky verze 4.5&quot;">​</a></h1><p>Změn po vydání verze 4.4 není mnoho, ale přesto jsou tak zásadní, že vám mohou pomoci usnadnit práci ještě více než doposud. Věříme, že i tentokrát budete z novinek nadšeni.</p><h2 id="prehledy-ve-stavebnim-deniku-prosly-promenou" tabindex="-1">PŘEHLEDY ve Stavebním deníku prošly proměnou <a class="header-anchor" href="#prehledy-ve-stavebnim-deniku-prosly-promenou" aria-label="Permalink to &quot;PŘEHLEDY ve Stavebním deníku prošly proměnou&quot;">​</a></h2><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+i+'" alt="" width="600" loading="lazy"><br></p></div><p>Doposud bylo možné procházet si přehledy pouze skrze stavbu a deník, na kterém se uživatel aktuálně nacházel. Nyní jsme umožnili uživateli <strong>vybrat si kterýkoliv deník, ke kterému má přístup (a je jedno, na které stavbě či doméně se nachází), bez nutnosti překlikávat se jinam</strong>. Nad volbou přehledu vznikl řádek s poli pro výběr domény / stavby / deníku, jehož data uživatele zajímají.</p><p>Dále také přibyl <strong>sloupec na konci tabulky se součty hodnot jednotlivých řádků</strong>.</p><h2 id="moznost-vyuziti-ai-umele-inteligence" tabindex="-1">Možnost využití AI (umělé inteligence) <a class="header-anchor" href="#moznost-vyuziti-ai-umele-inteligence" aria-label="Permalink to &quot;Možnost využití AI (umělé inteligence)&quot;">​</a></h2><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+s+'" alt="" width="600" loading="lazy"><br></p></div><p>V sekcích <strong>Provedené práce</strong> a <strong>Další záznamy</strong> jsme pro vás připravili možnost využít <strong>vygenerování záznamu pomocí AI</strong> při vkládání nového záznamu.</p><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+l+'" alt="" width="600" loading="lazy"><br></p></div><p>Na základě fotky nebo fotek vygeneruje Chat GPT popis stavebních prací, jakožto zápis do stavebního deníku. <strong>Uživatel může znění ovlivnit tím, že zadá výrazy, které mají být ve výsledném textu zahrnuty.</strong></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Naše doporučení:</strong></p><ul><li>Fotky by měly zachycovat konkrétní práci, nikoli globální pohled na stavbu, protože AI se snaží popsat vše, co na fotce vidí.</li><li>Foťte práce v jejich průběhu, nikoli výsledný stav.</li><li>Využívejte možnost ovlivnit obsah zápisu pomocí zadaných výrazů, kde upřesníte konkrétní část stavby, způsob nebo podmínky provádění. Bez těchto výrazů AI vygeneruje obecný popis obrázku, v němž ale budou chybět informace, které jsou z pohledu stavebního deníku zásadní.</li></ul></div><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+r+'" alt="" width="600" loading="lazy"><br></p></div><p>Text vytvořený AI je vložen do pole <strong>Popis</strong> záznamu a je možné jej následně upravovat.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Možnost generovat záznamy přes AI je možné pouze u nově vkládaných záznamů - nehledejte tuto funkci v editaci stávajících záznamů.</p><p><strong>Nezapomeňte, že AI je pouze nástroj, který může ulehčit nebo urychlit některé popisy - zodpovědnost za záznam s takto vygenerovanými texty je stále uživatel - autor daného záznamu.</strong></p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Tato funkce je dostupná pro webové rozhraní i pro mobilní aplikaci.</p></div>',16)])])}const h=o(p,[["render",v]]);export{y as __pageData,h as default};
